            strictly '25.4.0'
        }
    }
}

gameActivityImportAdditions.insert:
import android.preference.PreferenceManager;
import com.google.android.gms.ads.AdError;
import com.google.android.gms.ads.AdRequest;
import com.google.android.gms.ads.AdValue;
import com.google.android.gms.ads.FullScreenContentCallback;
import com.google.android.gms.ads.LoadAdError;
import com.google.android.gms.ads.MobileAds;
import com.google.android.gms.ads.OnPaidEventListener;
import com.google.android.gms.ads.OnUserEarnedRewardListener;
import com.google.android.gms.ads.RequestConfiguration;
import com.google.android.gms.ads.initialization.AdapterStatus;
import com.google.android.gms.ads.initialization.InitializationStatus;
import com.google.android.gms.ads.initialization.OnInitializationCompleteListener;
import com.google.android.gms.ads.rewarded.RewardItem;
import com.google.android.gms.ads.rewarded.RewardedAd;
import com.google.android.gms.ads.rewarded.RewardedAdLoadCallback;
import com.google.android.gms.ads.rewarded.ServerSideVerificationOptions;
import java.util.Arrays;
import java.util.HashMap;
import java.util.HashSet;
import java.util.Map;
import java.util.Set;

gameActivityClassAdditions.insert:
private RewardedAd openMobileRewardedAd = null;
private boolean openMobileRewardedAdLoading = false;
private boolean openMobileRewardedAdsInitialized = false;
private static final int OPEN_MOBILE_DATA_PROCESSING_STANDARD = 2;
private static final int OPEN_MOBILE_DATA_PROCESSING_RESTRICTED = 3;
private boolean openMobileRewardedAdsInitializing = false;
private InitializationStatus openMobileRewardedAdsInitializationStatus = null;
private long openMobileActiveRewardedShowRequestId = 0;
private final Map<Long, RewardedAd> openMobileLoadedRewardedAds = new HashMap<>();
private final Set<Long> openMobileRewardedAdLoadRequests = new HashSet<>();

public native void nativeOpenMobileAdsInitializationCompleted(long requestId);
public native void nativeOpenMobileAdsInitializationFailed(long requestId, String errorMessage);
public native void nativeOpenMobileAdsAdapterInitializationStatus(
    long requestId,
    String adapterName,
    boolean ready,
    long latencyMilliseconds,
    String description
);
public native void nativeOpenMobileRewardedAdLoaded(long requestId);
public native void nativeOpenMobileRewardedAdShown(long requestId);
public native void nativeOpenMobileRewardedAdImpression(long requestId);
public native void nativeOpenMobileRewardedAdClicked(long requestId);
public native void nativeOpenMobileRewardedAdRevenuePaid(
    long requestId,
    long valueMicros,
    String currencyCode,
    int precision
);
public native void nativeOpenMobileRewardedAdEarned(
    long requestId,
    int networkAmount,
    String networkRewardType
);
public native void nativeOpenMobileRewardedAdClosed(long requestId);
public native void nativeOpenMobileRewardedAdFailed(long requestId, String errorMessage);
public native void nativeOpenMobileRewardedAdLoadCompleted(long requestId);
public native void nativeOpenMobileRewardedAdLoadFailed(long requestId, String errorMessage);

private void reportOpenMobileAdsAdapterInitializationStatuses(
    long requestId,
    InitializationStatus initializationStatus
)
{
    if (initializationStatus == null)
    {
        return;
    }
    for (Map.Entry<String, AdapterStatus> entry
        : initializationStatus.getAdapterStatusMap().entrySet())
    {
        AdapterStatus status = entry.getValue();
        if (status == null)
        {
            continue;
        }
        nativeOpenMobileAdsAdapterInitializationStatus(
            requestId,
            entry.getKey(),
            status.getInitializationState() == AdapterStatus.State.READY,
            status.getLatency(),
            status.getDescription()
        );
    }
}

public boolean AndroidThunkJava_InitializeOpenMobileRewardedAds(
    final long requestId,
    final int childDirectedTreatment,
    final int underAgeOfConsent,
    final String[] testDeviceIdentifiers,
    final String maxAdContentRating
)
{
    try
    {
        GameActivity.this.runOnUiThread(new Runnable()
        {
            @Override
            public void run()
            {
                try
                {
                    RequestConfiguration.Builder configuration =
                        MobileAds.getRequestConfiguration().toBuilder()
                            .setTagForChildDirectedTreatment(childDirectedTreatment)
                            .setTagForUnderAgeOfConsent(underAgeOfConsent)
                            .setTestDeviceIds(Arrays.asList(testDeviceIdentifiers));
                    if (maxAdContentRating != null && maxAdContentRating.length() > 0)
                    {
                        configuration.setMaxAdContentRating(maxAdContentRating);
                    }
                    MobileAds.setRequestConfiguration(configuration.build());

                    if (openMobileRewardedAdsInitialized)
                    {
                        reportOpenMobileAdsAdapterInitializationStatuses(
                            requestId,
                            openMobileRewardedAdsInitializationStatus
                        );
                        nativeOpenMobileAdsInitializationCompleted(requestId);
                        return;
                    }
                    if (openMobileRewardedAdsInitializing)
                    {
                        nativeOpenMobileAdsInitializationFailed(
                            requestId,
                            "AdMob SDK initialization is already in progress."
                        );
                        return;
                    }

                    openMobileRewardedAdsInitializing = true;
                    MobileAds.initialize(activityContext, new OnInitializationCompleteListener()
                    {
                        @Override
                        public void onInitializationComplete(InitializationStatus initializationStatus)
                        {
                            openMobileRewardedAdsInitializing = false;
                            openMobileRewardedAdsInitialized = true;
                            openMobileRewardedAdsInitializationStatus = initializationStatus;
                            Log.debug("OpenMobile rewarded Google ads initialized");
                            reportOpenMobileAdsAdapterInitializationStatuses(
                                requestId,
                                initializationStatus
                            );
                            nativeOpenMobileAdsInitializationCompleted(requestId);
                        }
                    });
                }
                catch (Exception exception)
                {
                    openMobileRewardedAdsInitializing = false;
                    nativeOpenMobileAdsInitializationFailed(
                        requestId,
                        "AdMob SDK initialization failed: " + exception.getMessage()
                    );
                }
            }
        });
        return true;
    }
    catch (Exception exception)
    {
        Log.error("OpenMobile AdMob initialization could not be scheduled: " + exception.getMessage());
        return false;
    }
}

public void AndroidThunkJava_ShutdownOpenMobileRewardedAds()
{
    GameActivity.this.runOnUiThread(new Runnable()
    {
        @Override
        public void run()
        {
            openMobileRewardedAd = null;
            openMobileRewardedAdLoading = false;
            openMobileActiveRewardedShowRequestId = 0;
            openMobileLoadedRewardedAds.clear();
            openMobileRewardedAdLoadRequests.clear();
        }
    });
}

public boolean AndroidThunkJava_LoadOpenMobileRewardedAd(
    final String adUnitId,
    final long requestId,
    final int dataProcessingMode
)
{
    try
    {
        GameActivity.this.runOnUiThread(new Runnable()
        {
            @Override
            public void run()
            {
                if (adUnitId == null || adUnitId.trim().length() == 0)
                {
                    nativeOpenMobileRewardedAdLoadFailed(
                        requestId,
                        "The Android rewarded ad unit ID is empty."
                    );
                    return;
                }
                if (
                    openMobileRewardedAdLoadRequests.contains(requestId)
                    || openMobileLoadedRewardedAds.containsKey(requestId)
                )
                {
                    nativeOpenMobileRewardedAdLoadFailed(
                        requestId,
                        "The Android rewarded load request is already active."
                    );
                    return;
                }

                openMobileRewardedAdLoadRequests.add(requestId);
                if (dataProcessingMode == OPEN_MOBILE_DATA_PROCESSING_RESTRICTED)
                {
                    PreferenceManager.getDefaultSharedPreferences(activityContext)
                        .edit().putInt("gad_rdp", 1).apply();
                }
                else if (dataProcessingMode == OPEN_MOBILE_DATA_PROCESSING_STANDARD)
                {
                    PreferenceManager.getDefaultSharedPreferences(activityContext)
                        .edit().remove("gad_rdp").apply();
                }
                try
                {
                    RewardedAd.load(
                        activityContext,
                        adUnitId,
                        new AdRequest.Builder().build(),
                        new RewardedAdLoadCallback()
                        {
                            @Override
                            public void onAdLoaded(RewardedAd rewardedAd)
                            {
                                if (!openMobileRewardedAdLoadRequests.remove(requestId))
                                {
                                    return;
                                }
                                openMobileLoadedRewardedAds.put(requestId, rewardedAd);
                                nativeOpenMobileRewardedAdLoadCompleted(requestId);
                            }

                            @Override
                            public void onAdFailedToLoad(LoadAdError loadAdError)
                            {
                                if (!openMobileRewardedAdLoadRequests.remove(requestId))
                                {
                                    return;
                                }
                                nativeOpenMobileRewardedAdLoadFailed(
                                    requestId,
                                    "Rewarded ad failed to load: " + loadAdError.getMessage()
                                );
                            }
                        }
                    );
                }
                catch (Exception exception)
                {
                    openMobileRewardedAdLoadRequests.remove(requestId);
                    nativeOpenMobileRewardedAdLoadFailed(
                        requestId,
                        "Rewarded ad load could not start: " + exception.getMessage()
                    );
                }
            }
        });
        return true;
    }
    catch (Exception exception)
    {
        Log.error("OpenMobile rewarded ad load failed: " + exception.getMessage());
        return false;
    }
}

public void AndroidThunkJava_CancelOpenMobileRewardedAdLoad(final long requestId)
{
    GameActivity.this.runOnUiThread(new Runnable()
    {
        @Override
        public void run()
        {
            openMobileRewardedAdLoadRequests.remove(requestId);
            openMobileLoadedRewardedAds.remove(requestId);
        }
    });
}

public boolean AndroidThunkJava_ShowOpenMobileRewardedAd(
    final long loadedRequestId,
    final long showRequestId,
    final String serverVerificationCustomData
)
{
    try
    {
        GameActivity.this.runOnUiThread(new Runnable()
        {
            @Override
            public void run()
            {
                if (
                    openMobileActiveRewardedShowRequestId != 0
                    || openMobileRewardedAdLoading
                    || openMobileRewardedAd != null
                )
                {
                    nativeOpenMobileRewardedAdFailed(
                        showRequestId,
                        "A rewarded ad is already loading or showing."
                    );
                    return;
                }

                final RewardedAd rewardedAd = openMobileLoadedRewardedAds.remove(
                    loadedRequestId
                );
                if (rewardedAd == null)
                {
                    nativeOpenMobileRewardedAdFailed(
                        showRequestId,
                        "The cached Android rewarded ad is unavailable or already consumed."
                    );
                    return;
                }

                openMobileActiveRewardedShowRequestId = showRequestId;
                try
                {
                    if (
                        serverVerificationCustomData != null
                        && serverVerificationCustomData.length() > 0
                    )
                    {
                        rewardedAd.setServerSideVerificationOptions(
                            new ServerSideVerificationOptions.Builder()
                                .setCustomData(serverVerificationCustomData)
                                .build()
                        );
                    }
                    rewardedAd.setFullScreenContentCallback(
                        new FullScreenContentCallback()
                        {
                            @Override
                            public void onAdShowedFullScreenContent()
                            {
                                nativeOpenMobileRewardedAdShown(showRequestId);
                            }

                            @Override
                            public void onAdImpression()
                            {
                                nativeOpenMobileRewardedAdImpression(showRequestId);
                            }

                            @Override
                            public void onAdClicked()
                            {
                                nativeOpenMobileRewardedAdClicked(showRequestId);
                            }

                            @Override
                            public void onAdDismissedFullScreenContent()
                            {
                                openMobileActiveRewardedShowRequestId = 0;
                                nativeOpenMobileRewardedAdClosed(showRequestId);
                            }

                            @Override
                            public void onAdFailedToShowFullScreenContent(AdError adError)
                            {
                                openMobileActiveRewardedShowRequestId = 0;
                                nativeOpenMobileRewardedAdFailed(
                                    showRequestId,
                                    "Rewarded ad failed to show: " + adError.getMessage()
                                );
                            }
                        }
                    );
                    rewardedAd.setOnPaidEventListener(new OnPaidEventListener()
                    {
                        @Override
                        public void onPaidEvent(AdValue adValue)
                        {
                            nativeOpenMobileRewardedAdRevenuePaid(
                                showRequestId,
                                adValue.getValueMicros(),
                                adValue.getCurrencyCode(),
                                adValue.getPrecisionType()
                            );
                        }
                    });
                    rewardedAd.show(
                        GameActivity.this,
                        new OnUserEarnedRewardListener()
                        {
                            @Override
                            public void onUserEarnedReward(RewardItem rewardItem)
                            {
                                nativeOpenMobileRewardedAdEarned(
                                    showRequestId,
                                    rewardItem.getAmount(),
                                    rewardItem.getType()
                                );
                            }
                        }
                    );
                }
                catch (Exception exception)
                {
                    openMobileActiveRewardedShowRequestId = 0;
                    nativeOpenMobileRewardedAdFailed(
                        showRequestId,
                        "Rewarded ad could not be presented: " + exception.getMessage()
                    );
                }
            }
        });
        return true;
    }
    catch (Exception exception)
    {
        Log.error("OpenMobile cached rewarded ad could not be scheduled: " + exception.getMessage());
        return false;
    }
}

public boolean AndroidThunkJava_RequestAndShowOpenMobileRewardedAd(
    final String adUnitId,
    final long requestId
)
{
    try
    {
        GameActivity.this.runOnUiThread(new Runnable()
        {
            @Override
            public void run()
            {
                if (
                    openMobileRewardedAdLoading
                    || openMobileRewardedAd != null
                    || openMobileActiveRewardedShowRequestId != 0
                )
                {
                    nativeOpenMobileRewardedAdFailed(
                        requestId,
                        "A rewarded ad is already loading or showing."
                    );
                    return;
                }

                if (adUnitId == null || adUnitId.trim().length() == 0)
                {
                    nativeOpenMobileRewardedAdFailed(
                        requestId,
                        "The Android rewarded ad unit ID is empty."
                    );
                    return;
                }

                openMobileRewardedAdLoading = true;
                RewardedAd.load(
                    activityContext,
                    adUnitId,
                    new AdRequest.Builder().build(),
                    new RewardedAdLoadCallback()
                    {
                        @Override
                        public void onAdLoaded(RewardedAd rewardedAd)
                        {
                            openMobileRewardedAdLoading = false;
                            openMobileRewardedAd = rewardedAd;
                            nativeOpenMobileRewardedAdLoaded(requestId);

                            rewardedAd.setFullScreenContentCallback(
                                new FullScreenContentCallback()
                                {
                                    @Override
                                    public void onAdShowedFullScreenContent()
                                    {
                                        nativeOpenMobileRewardedAdShown(requestId);
                                    }

                                    @Override
                                    public void onAdDismissedFullScreenContent()
                                    {
                                        openMobileRewardedAd = null;
                                        nativeOpenMobileRewardedAdClosed(requestId);
                                    }

                                    @Override
                                    public void onAdFailedToShowFullScreenContent(AdError adError)
                                    {
                                        openMobileRewardedAd = null;
                                        nativeOpenMobileRewardedAdFailed(
                                            requestId,
                                            "Rewarded ad failed to show: " + adError.getMessage()
                                        );
                                    }
                                }
                            );

                            try
                            {
                                rewardedAd.show(
                                    GameActivity.this,
                                    new OnUserEarnedRewardListener()
                                    {
                                        @Override
                                        public void onUserEarnedReward(RewardItem rewardItem)
                                        {
                                            nativeOpenMobileRewardedAdEarned(
                                                requestId,
                                                rewardItem.getAmount(),
                                                rewardItem.getType()
                                            );
                                        }
                                    }
                                );
                            }
                            catch (Exception exception)
                            {
                                openMobileRewardedAd = null;
                                nativeOpenMobileRewardedAdFailed(
                                    requestId,
                                    "Rewarded ad could not be presented: " + exception.getMessage()
                                );
                            }
                        }

                        @Override
                        public void onAdFailedToLoad(LoadAdError loadAdError)
                        {
                            openMobileRewardedAdLoading = false;
                            openMobileRewardedAd = null;
                            nativeOpenMobileRewardedAdFailed(
                                requestId,
                                "Rewarded ad failed to load: " + loadAdError.getMessage()
                            );
                        }
                    }
                );
            }
        });
        return true;
    }
    catch (Exception exception)
    {
        Log.error("OpenMobile rewarded ad request failed: " + exception.getMessage());
        return false;
    }
}

